-- 73 regular (non-seasonal) snack items from wdw_snacks.xlsx. 4 items
-- (LeFou's Brew, Smoked Turkey Leg, School Bread, Ronto Wrap) already
-- existed and are merged into their ids rather than duplicated; park is
-- deliberately excluded from the upsert so Smoked Turkey Leg keeps its
-- existing 'All parks' value instead of narrowing to the Magic Kingdom
-- location this sheet happened to list it under.
--
-- 25 of the 73 items are sold at a vendor that already has its own catalog
-- row (e.g. Ronto Wrap -> Ronto Roasters) -- those get a real booth_id
-- link instead of a plain-text location_detail, reusing the same
-- relational pattern the Food & Wine items use for their booths.
on conflict (id) do update set
  name=excluded.name, category=excluded.category, description=excluded.description,
  price_label=excluded.price_label, price_mid=excluded.price_mid, location_detail=excluded.location_detail,
  item_type=excluded.item_type, dining_plan_credits=excluded.dining_plan_credits, tags=excluded.tags, booth_id=excluded.booth_id;
