insert into catalog_items (id, name, park, category, description, price_label, price_mid, location_detail, item_type, dining_plan_credits, tags, booth_id) values
  ('s-dole-whip-pineapple-float', 'Dole Whip Pineapple Float', 'MK', 'snack', 'The undisputed king of Disney snacks. Pineapple soft-serve swirled into pineapple juice — tangy, dairy-free, and endlessly refreshing. The Tropical Serenade float variation is a crowd favorite.', '~$6.99', 6.99, 'Aloha Isle', 'food', 'Snack Credit', ARRAY['Plant-based']::text[], null),
  ('s-pineapple-upside-down-cake', 'Pineapple Upside Down Cake', 'MK', 'snack', 'Pineapple upside-down cake topped with your choice of Dole Whip. A filling, dessert-forward alternative to the classic float — often overlooked in favor of the float, which means shorter wait.', '~$6.99', 6.99, 'Aloha Isle', 'food', 'Snack Credit', null, null),
  ('s-i-lava-you-float', 'I Lava You Float', 'MK', 'snack', 'Dole Whip Orange with Fanta Strawberry soda, passion fruit syrup, and popping candy. A more elaborate, photogenic alternative to the classic Dole Whip float. Adventureland staple.', '~$6.99', 6.99, 'Sunshine Tree Terrace', 'drink', 'Snack Credit', ARRAY['Plant-based']::text[], null),
  ('s-cheeseburger-spring-rolls', 'Cheeseburger Spring Rolls', 'MK', 'snack', 'Crispy spring rolls stuffed with beef, cheddar, and pickles — essentially a cheeseburger in spring roll form. Consistently rated the best savory snack in Magic Kingdom. Sell out early on busy days.', '~$8.99', 8.99, 'Adventureland Spring Roll Cart', 'food', 'Snack Credit', null, null),
  ('s-gaston-s-tavern-cinnamon-roll', 'Gaston''s Tavern Cinnamon Roll', 'MK', 'snack', 'A massive, gooey, icing-loaded cinnamon roll — one of the most beloved snacks in any Disney park. Ask for extra icing to take it to the next level. Often shared between two guests.', '~$6.49', 6.49, null, 'food', 'Snack Credit', null, 's-gaston-s-tavern'),
  ('s-lefou', 'LeFou''s Brew', 'MK', 'snack', 'Frozen apple juice with toasted marshmallow foam, served in a collectible stein. Non-alcoholic and kid-friendly — one of the most popular themed drinks in the parks.', '~$5.99', 5.99, null, 'drink', 'Snack Credit', ARRAY['Plant-based']::text[], 's-gaston-s-tavern'),
  ('s-mickey-premium-ice-cream-bar', 'Mickey Premium Ice Cream Bar', 'MK', 'snack', 'Vanilla ice cream on a stick, dipped in dark chocolate, shaped like Mickey''s head. The most photographed Disney snack in existence — eat it fast in the Florida heat.', '~$6.50', 6.5, 'Ice Cream Carts (parkwide)', 'food', 'Snack Credit', null, null),
  ('s-mickey-pretzel', 'Mickey Pretzel', 'MK', 'snack', 'A soft, warm pretzel shaped like Mickey Mouse — one of the most iconic Disney World snacks. Available plain or with a side of cheese sauce. Found at carts throughout the park.', '~$7.49', 7.49, 'Pretzel Carts (parkwide)', 'food', 'Snack Credit', null, null),
  ('s-turkeyleg', 'Smoked Turkey Leg', 'MK', 'snack', 'A massive, smoky, ham-flavored turkey leg — a Disney institution since the 1980s. You can smell them from three lands away. The original walk-and-eat Disney flex.', '~$13.49', 13.49, 'Frontierland / Liberty Square Carts', 'food', 'Snack Credit', null, null),
  ('s-candied-bacon-skewer', 'Candied Bacon Skewer', 'MK', 'snack', 'Thick-cut bacon on a stick coated in brown sugar. Sweet, salty, smoky, and surprisingly portable. A longtime fan favorite tucked away in a low-key Frontierland cart.', '~$5.99', 5.99, 'Westward Ho', 'food', 'Snack Credit', null, null),
  ('s-mickey-bacon-pecan-caramel', 'Mickey Bacon-Pecan-Caramel Cinnamon Roll', 'MK', 'snack', 'Mickey-shaped cinnamon roll combining caramel, bacon, and pecans in a sweet-and-savory combination. Only available at breakfast — grab it first thing in the morning.', '~$7.99', 7.99, 'Westward Ho', 'food', 'Snack Credit', null, null),
  ('s-cream-cheese-stuffed-pretzel', 'Cream Cheese Stuffed Pretzel', 'MK', 'snack', 'A soft pretzel stuffed with warm sweet cream cheese. More indulgent than the standard Mickey pretzel, and a perennial best-of recommendation from Disney food bloggers.', '~$7.99', 7.99, null, 'food', 'Snack Credit', null, 's-the-lunching-pad'),
  ('s-main-street-confectionary', 'Main Street Confectionary Treats', 'MK', 'snack', 'The park''s candy shop with rotating hand-dipped apples, fudge, rice crispy treats, and themed desserts. Items rotate frequently — the chocolate-dipped apples and Mickey-shaped rice crispy treats are year-round staples.', '$7–$12', 9.5, 'Main Street Confectionary', 'food', 'Snack Credit', null, null),
  ('s-caramel-popcorn', 'Caramel Popcorn', 'MK', 'snack', 'Disney''s famous caramel corn — sweet, crunchy, and available throughout the park in souvenir buckets. The seasonal specialty popcorn flavors are worth seeking out.', '~$5.50', 5.5, 'Popcorn Carts (parkwide)', 'food', 'Snack Credit', ARRAY['Plant-based']::text[], null),
  ('s-schoolbread', 'School Bread', 'EPCOT', 'snack', 'A sweet cardamom bun filled with vanilla custard and topped with toasted coconut — a Norwegian staple and one of EPCOT''s most beloved snacks. A hidden gem that first-timers often walk right past.', '~$6.29', 6.29, null, 'food', 'Snack Credit', null, 's-kringla-bakeri-og-kafe'),
  ('s-orange-cream-cheese-cinnamon', 'Orange Cream Cheese Cinnamon Roll', 'EPCOT', 'snack', 'A newer addition to the Norway bakery with a bright citrusy twist on the classic cinnamon roll. Some food bloggers have declared it a rival to Gaston''s Tavern cinnamon roll. Worth the detour.', '~$5.99', 5.99, null, 'food', 'Snack Credit', null, 's-kringla-bakeri-og-kafe'),
  ('s-chocolate-croissant', 'Chocolate Croissant', 'EPCOT', 'snack', 'An authentic French pain au chocolat — buttery, flaky, and filled with dark chocolate. Consistently one of the most recommended snacks in all of EPCOT. Go early before they sell out.', '~$5.79', 5.79, null, 'food', 'Snack Credit', null, 's-les-halles-boulangerie-p'),
  ('s-ham-and-cheese-baguette', 'Ham and Cheese Baguette', 'EPCOT', 'snack', 'A proper French ham and cheese on a crusty baguette — simple, excellent, and shockingly good for a theme park. The best savory grab-and-go in EPCOT''s World Showcase.', '~$7.99', 7.99, null, 'food', 'Snack Credit', null, 's-les-halles-boulangerie-p'),
  ('s-ice-cream-brioche-sandwich', 'Ice Cream Brioche Sandwich', 'EPCOT', 'snack', 'Croque Glacé — warm toasted brioche filled with two scoops of artisan ice cream or sorbet. The ice cream is made in-house with French flavors including salted butter caramel, lavender honey, and seasonal specials.', '~$9.99', 9.99, 'L''Artisan des Glaces', 'food', 'Snack Credit', null, null),
  ('s-ice-cream-martini', 'Ice Cream Martini', 'EPCOT', 'snack', 'Artisan ice cream blended with your choice of liqueur — Baileys, Grand Marnier, Chambord. A grown-ups-only indulgence in the France pavilion. Not on the dining plan. One of EPCOT''s most underrated adult treats.', '~$12.99', 12.99, 'L''Artisan des Glaces', 'drink', 'N/A', null, null),
  ('s-karamell-k-che-caramel-cookie', 'Karamell-Küche Caramel Cookie Sandwich', 'EPCOT', 'snack', 'Rotating caramel cookie sandwiches from the Werther''s Original shop in the Germany pavilion. Salted caramel buttercream is the star — flavors change frequently but are always exceptional.', '~$5.99', 5.99, 'Karamell-Küche', 'food', 'Snack Credit', null, null),
  ('s-karamell-k-che-caramel-corn', 'Karamell-Küche Caramel Corn', 'EPCOT', 'snack', 'Warm, fresh caramel corn from the Werther''s shop in Germany — buttery, freshly made, and significantly better than standard park popcorn. A Werther''s Original product done right.', '~$5.49', 5.49, 'Karamell-Küche', 'food', 'Snack Credit', null, null),
  ('s-pretzel-nuggets-with-beer', 'Pretzel Nuggets with Beer Cheese', 'EPCOT', 'snack', 'Soft pretzel nuggets with BBQ seasoning and house-made beer cheese fondue. A frequent best-of recommendation from Disney Food Blog and others. One cup of cheese is never enough.', '~$8.49', 8.49, null, 'food', 'Snack Credit', null, 'kiosk-block-hans'),
  ('s-maple-popcorn', 'Maple Popcorn', 'EPCOT', 'snack', 'Sweet, buttery maple-flavored popcorn from the Canada pavilion. A uniquely Canadian twist on the classic park popcorn — sweet, salty, and dangerously addictive. Popular souvenir bucket option.', '~$6.50', 6.5, 'Canada Popcorn Cart', 'food', 'Snack Credit', ARRAY['Plant-based']::text[], null),
  ('s-bratwurst', 'Bratwurst', 'EPCOT', 'snack', 'A classic German bratwurst served in a roll with sauerkraut and mustard. One of the most authentic and satisfying savory options in World Showcase — pairs perfectly with a German beer.', '~$10.99', 10.99, null, 'food', 'QS Credit', null, 's-sommerfest'),
  ('s-fish-and-chips', 'Fish and Chips', 'EPCOT', 'snack', 'Classic British-style battered fish and chips served in a paper cone at the UK pavilion window. Simple, consistently good, and one of the better value savory snacks in World Showcase.', '~$11.99', 11.99, null, 'food', 'Snack Credit', null, 's-yorkshire-county-fish-shop'),
  ('s-rontowrap', 'Ronto Wrap', 'HS', 'snack', 'Roasted pork and grilled pork sausage with tangy slaw and peppercorn sauce wrapped in warm pita. One of the most beloved snacks in all of Walt Disney World — filling enough to be a full meal. Also available at Docking Bay 7 after 3 PM when Ronto Roasters closes.', '~$14.99', 14.99, null, 'food', 'QS Credit', null, 's-ronto-roasters'),
  ('s-zucchi-wrap', 'Zucchi Wrap', 'HS', 'snack', 'The plant-based version of the Ronto Wrap — marinated zucchini and roasted vegetables in warm pita with the same peppercorn sauce. A rare plant-based option that food bloggers rave about.', '~$14.99', 14.99, null, 'food', 'QS Credit', ARRAY['Plant-based']::text[], 's-ronto-roasters'),
  ('s-carrot-cake-whoopie-pie', 'Carrot Cake Whoopie Pie', 'HS', 'snack', 'Two thick spiced carrot cake layers sandwiched with generous cream cheese frosting. A longtime fan favorite and one of the most iconic snacks at Hollywood Studios — a reliable must-order every visit.', '~$5.99', 5.99, null, 'food', 'Snack Credit', null, 's-trolley-car-caf'),
  ('s-totchos', 'Totchos', 'HS', 'snack', 'Tater tots loaded with beef chili, cheddar cheese sauce, and sour cream. Messy, nostalgic, and deeply satisfying. A Toy Story Land staple — shareable for two guests as a snack.', '~$9.99', 9.99, null, 'food', 'QS Credit', null, 's-woody-s-lunch-box'),
  ('s-lunch-box-tart', 'Lunch Box Tart', 'HS', 'snack', 'A warm hand-held tart with rotating seasonal fillings — blueberry lemon, strawberry, and seasonal flavors. Simple, portable, and a great companion to the Totchos. Flavors change periodically.', '~$4.49', 4.49, null, 'food', 'Snack Credit', null, 's-woody-s-lunch-box'),
  ('s-buffalo-chicken-waffle-bowl', 'Buffalo Chicken Waffle Bowl', 'HS', 'snack', 'Buffalo chicken with coleslaw and mashed potatoes served in a crispy waffle bowl. Spicy, crunchy, creamy, and one of the best savory snacks in the park. Popular enough to generate its own fan following.', '~$11.49', 11.49, null, 'food', 'QS Credit', null, 's-fairfax-fare'),
  ('s-bbq-brisket-waffle-bowl', 'BBQ Brisket Waffle Bowl', 'HS', 'snack', 'Braised beef brisket with BBQ sauce, jalapeños, red onion, bacon, and corn chips served over mashed potatoes in a waffle bowl with house-made queso sauce. A loaded, filling snack for serious eaters.', '~$11.99', 11.99, null, 'food', 'QS Credit', null, 's-fairfax-fare'),
  ('s-bavarian-pretzel-with-beer', 'Bavarian Pretzel with Beer Cheese', 'HS', 'snack', 'A warm Bavarian-style soft pretzel with beer cheese fondue and whole-grain mustard. Widely considered the best pretzel on Disney property. Pair with a craft beer for the ideal Hollywood Studios mid-day break.', '~$9.99', 9.99, 'Baseline Tap House', 'food', 'Snack Credit', null, null),
  ('s-pink-milk', 'Pink Milk', 'HS', 'snack', 'Bright pink, fruity batuu-berry flavored milk — the sweeter, more accessible sibling to the famous Blue and Green Milk. Non-alcoholic. Photogenic and universally liked, even by those who don''t enjoy the Blue Milk.', '~$7.99', 7.99, 'Milk Stand (Galaxy''s Edge)', 'drink', 'Snack Credit', null, null),
  ('s-blue-milk', 'Blue Milk', 'HS', 'snack', 'The legendary Star Wars blue milk — a plant-based frozen blend of coconut and rice milk with dragon fruit, passion fruit, and watermelon flavors. Non-alcoholic. Polarizing but iconic — a must for Star Wars fans.', '~$7.99', 7.99, 'Milk Stand (Galaxy''s Edge)', 'drink', 'Snack Credit', ARRAY['Plant-based']::text[], null),
  ('s-funnel-cake', 'Funnel Cake', 'HS', 'snack', 'Large funnel cakes in classic and topped variations — strawberry, cookies ''n cream, and caramel-apple pie. One of the best snack values in the park: filling, affordable, and eligible for a snack credit on the dining plan.', '~$8.99', 8.99, 'Epic Eats', 'food', 'Snack Credit', null, null),
  ('s-pizza-planet-spring-rolls', 'Pizza Planet Spring Rolls', 'HS', 'snack', 'A 2026 addition to Toy Story Land — pizza-flavored spring rolls from a new kiosk near Alien Swirling Saucers. Already generating buzz on social media as a must-try new item.', '~$8.49', 8.49, 'Popcorn & Snacks Stand (Toy Story Land)', 'food', 'Snack Credit', null, null),
  ('s-night-blossom', 'Night Blossom', 'AK', 'snack', 'Layers of green apple and purple desert pear limeade slush topped with passion fruit boba balls. Beautiful, photogenic, and refreshing. One of the most Instagrammed drinks in Walt Disney World. Non-alcoholic.', '~$7.49', 7.49, 'Pongu Pongu', 'drink', 'Snack Credit', ARRAY['Plant-based']::text[], null),
  ('s-pongu-lumpia', 'Pongu Lumpia', 'AK', 'snack', 'A crispy spring roll stuffed with pineapple and cream cheese — sweet, crunchy, and portable. Sounds unusual but is one of the most recommended snacks in the park. Perfect before riding Flight of Passage.', '~$5.29', 5.29, 'Pongu Pongu', 'food', 'Snack Credit', null, null),
  ('s-rum-blossom', 'Rum Blossom', 'AK', 'snack', 'The adult version of the Night Blossom — the same limeade slush with Parrot Bay Coconut Rum. A popular choice for adults exploring Pandora. Not on the dining plan.', '~$13.49', 13.49, 'Pongu Pongu', 'drink', 'N/A', ARRAY['Plant-based']::text[], null),
  ('s-nightwraith-blaze', 'Nightwraith Blaze', 'AK', 'snack', 'A newer Pandora drink with blood orange, lychee, and wildberry flavors, served with glow cubes and popping pearls. Non-alcoholic with a boozy version also available. A 2025/2026 addition generating strong social buzz.', '~$7.99', 7.99, 'Pongu Pongu', 'drink', 'Snack Credit', ARRAY['Plant-based']::text[], null),
  ('s-satu-li-cheeseburger-steamed', 'Satu''li Cheeseburger Steamed Bao Bun', 'AK', 'snack', 'Fluffy steamed bao buns filled with cheeseburger ingredients — beef, cheese, pickles, and sauce. Light, fun, and addictive. An often-overlooked menu item at one of Disney''s best quick service restaurants.', '~$6.49', 6.49, null, 'food', 'QS Credit', null, 's-satu-li-canteen'),
  ('s-pulled-pork-fries', 'Pulled Pork Fries', 'AK', 'snack', 'Crinkle-cut fries loaded with pulled pork, BBQ sauce, and nacho cheese. A beloved Animal Kingdom staple — best enjoyed near the water with a view of Expedition Everest. Often called ''AJ''s Birthday Fries'' by fans of Disney Food Blog.', '~$10.49', 10.49, null, 'food', 'QS Credit', null, 's-flame-tree-barbecue'),
  ('s-cheesecake-pop', 'Cheesecake Pop', 'AK', 'snack', 'Rotating seasonal cheesecake on a stick — pumpkin in fall, cranberry-cherry in winter. Flavors change frequently. A newer addition to Flame Tree that has quickly become a fan favorite.', '~$5.99', 5.99, null, 'food', 'Snack Credit', null, 's-flame-tree-barbecue'),
  ('s-cookie-dough-brownie-ice', 'Cookie Dough Brownie Ice Cream Sandwich', 'AK', 'snack', 'Brownie base, vanilla ice cream center, and cookie dough top — the viral 2026 newcomer at Animal Kingdom. Generating serious buzz and lines. The spiritual successor to the old Dino-Bite ice cream sandwich.', '~$8.99', 8.99, 'Terra Treats', 'food', 'Snack Credit', null, null),
  ('s-nomad-lounge-churros', 'Nomad Lounge Churros', 'AK', 'snack', 'Fresh, hot churros served with chili-strawberry and vanilla crema dipping sauces. Widely considered the best churros on Disney property — significantly better than the standard cart churros. Walk-up, no reservation needed.', '~$8.99', 8.99, null, 'food', 'N/A', null, 'd-nomad-lounge'),
  ('s-cheese-stuffed-arepa', 'Cheese-stuffed Arepa', 'AK', 'snack', 'Colombian-style corn cakes stuffed with melted cheese, with pulled pork or pulled chicken options. Only available 11 AM–3 PM. An underrated Animal Kingdom gem — the cheese pull is exceptional.', '~$7.99', 7.99, 'Smiling Crocodile', 'food', 'Snack Credit', null, null),
  ('s-grilled-corn-on-the-cob', 'Grilled Corn on the Cob', 'AK', 'snack', 'African-spiced grilled corn with seasoned butter. A surprisingly flavorful ''healthier'' option at Animal Kingdom. The spice blend makes it far more interesting than standard theme park corn.', '~$5.99', 5.99, 'Harambe Fruit Market', 'food', 'Snack Credit', ARRAY['Plant-based']::text[], null),
  ('s-gideon-s-bakehouse-cookie', 'Gideon''s Bakehouse Cookie', 'DS', 'snack', 'Massive half-pound cookies baked fresh daily — the most famous bakery item at Walt Disney World. Classic flavors include Chocolate Chip, Peanut Butter Crunch, and Cookies & Cream. Monthly rotating flavors, hot cookie hours, and secret social-media-only items. Expect a line.', '~$8.00', 8.0, 'Gideon''s Bakehouse', 'food', 'N/A', null, null),
  ('s-dole-whip-flight', 'Dole Whip Flight', 'DS', 'snack', 'Three rotating Dole Whip flavors sampled together — the perfect option for indecisive guests. Disney Springs'' premier Dole Whip destination with more flavor variety than park Aloha Isle locations.', '~$9.99', 9.99, 'Swirls on the Water', 'food', 'N/A', ARRAY['Plant-based']::text[], null),
  ('s-crispy-mac-cheese-bites', 'Crispy Mac & Cheese Bites', 'DS', 'snack', 'Golden, crispy mac and cheese nuggets from the Wine Bar George to-go window. No reservation needed. One of the most recommended Disney Springs walk-up snacks from Disney food bloggers.', '~$10.00', 10.0, 'The Basket at Wine Bar George', 'food', 'N/A', null, null),
  ('s-chocolate-peanut-butter', 'Chocolate Peanut Butter Mousse Pie Cup', 'DS', 'snack', 'A mousse-filled cup that tastes like an oversized Reese''s cup — rich peanut butter mousse with chocolate ganache, topped with edible glitter. A pricier Disney Springs indulgence that Disney Food Blog calls ''true love.''', '~$15.00', 15.0, 'The Cake Bake Shop Bakery', 'food', 'N/A', null, null),
  ('s-blue-ribbon-pickle-dog', 'Blue Ribbon Pickle Dog', 'DS', 'snack', 'A hot dog wrapped in a dill pickle, battered, and fried, served with peanut butter dipping sauce. Sounds wild, tastes incredible. Blue Ribbon Corn Dogs at the BoardWalk has completely redefined the corn dog at Disney.', '~$12.99', 12.99, 'Blue Ribbon Corn Dogs', 'food', 'N/A', null, null),
  ('s-bottomless-truffle-fries', 'Bottomless Truffle Fries', 'DS', 'snack', 'Thin, crispy fries with parmesan and truffle aioli — available during Martini Hour (Mon–Fri, 3–6 PM) for $10, all-you-can-eat. One of the best snack deals on Disney property. Disney Food Blog''s top happy hour recommendation.', '~$10.00', 10.0, 'Summer House on the Lake', 'food', 'N/A', null, null),
  ('s-vivoli-il-gelato', 'Vivoli il Gelato', 'DS', 'snack', 'Artisan Italian gelato in rotating flavors from a renowned Florence gelateria. One of the most genuinely high-quality dessert options at Disney Springs. Fresh flavors daily — the stracciatella and pistachio are standouts.', '$5–$9', 7.0, 'Vivoli il Gelato', 'food', 'N/A', null, null),
  ('s-amorette-s-mini-dome-cake', 'Amorette''s Mini Dome Cake', 'DS', 'snack', 'A beautifully decorated Mickey-shaped dome cake — mousse layers over a sponge cake base with mirror glaze finish. One of the most photogenic items at Disney Springs and a popular gift item.', '~$8.99', 8.99, null, 'food', 'N/A', null, 's-amorette-s-patisserie'),
  ('s-everglazed-gourmet-donut', 'Everglazed Gourmet Donut', 'DS', 'snack', 'Creative gourmet doughnuts with rotating flavors — Nutella Boston Cream, Icon Donut (signature blue glaze), and seasonal specials. The cold brew ''toppers'' with a mini doughnut perched on top are a fan favorite.', '$5–$8', 6.5, 'Everglazed Doughnuts & Cold Brew', 'food', 'N/A', null, null),
  ('s-gasparilla-island-grill', 'Gasparilla Island Grill Mickey Waffles', 'GF', 'snack', 'Mickey-shaped Belgian waffles available 24 hours a day at the Grand Floridian''s quick service. The late-night option makes these a resort guest staple — good for early mornings before park opening too.', '~$7.49', 7.49, null, 'food', 'QS Credit', null, 's-gasparilla-island-grill'),
  ('s-cookie-croissant', 'Cookie Croissant', 'CR', 'snack', 'A warm, flaky croissant filled with chocolate chip cookie dough, topped with powdered sugar and milk chocolate drizzle. A 2024 addition that has become one of the most talked-about resort snacks. The hybrid texture is extraordinary.', '~$6.99', 6.99, null, 'food', 'Snack Credit', null, 's-contempo-cafe'),
  ('s-mickey-rice-crispy-treat', 'Mickey Rice Crispy Treat', 'CR', 'snack', 'A Mickey-shaped rice crispy treat — a classic Disney confection available at multiple locations but particularly popular at Contempo Cafe. Simple, iconic, shareable.', '~$5.99', 5.99, null, 'food', 'Snack Credit', null, 's-contempo-cafe'),
  ('s-dole-whip-float-pineapple', 'Dole Whip Float (Pineapple Lanai)', 'POLY', 'snack', 'The only resort Dole Whip stand — same great pineapple soft-serve as the park, but often with a shorter wait and a beautiful outdoor setting near the Seven Seas Lagoon. A great monorail crawl stop.', '~$6.99', 6.99, null, 'food', 'Snack Credit', ARRAY['Plant-based']::text[], 's-pineapple-lanai'),
  ('s-tonga-toast', 'Tonga Toast', 'POLY', 'snack', 'Banana-stuffed sourdough bread, deep fried and rolled in cinnamon sugar, served with strawberry compote. One of the most famous resort breakfast items at Walt Disney World — a Polynesian institution.', '~$14.99', 14.99, null, 'food', 'QS Credit', null, 's-capt-cook-s'),
  ('s-mickey-beignets', 'Mickey Beignets', 'POFQ', 'snack', 'Mickey-shaped fried dough absolutely buried in powdered sugar. A Port Orleans French Quarter staple that Disney Food Blog ranks as a Disney World classic. Seasonal rotating flavors also available throughout the year.', '~$5.99', 5.99, null, 'food', 'Snack Credit', ARRAY['Plant-based']::text[], 's-scat-cat-s-club-cafe'),
  ('s-blue-ribbon-corn-dogs', 'Blue Ribbon Corn Dogs', 'BW', 'snack', 'Creative corn dogs including the Pickle Dog (hot dog wrapped in dill pickle, battered and fried with peanut butter dipping sauce), the Mexican Street Dog, and rotating specials. A Disney Food Blog 2026 top pick. Deep Fried Hawaiian Rolls are a must-order when available.', '$10–$14', 12.0, 'Blue Ribbon Corn Dogs', 'food', 'N/A', null, null),
  ('s-boardwalk-churros', 'BoardWalk Churros', 'BW', 'snack', 'Classic fried churros rolled in cinnamon sugar, available from carts along the BoardWalk promenade. A pleasant evening snack while strolling the waterfront between EPCOT and the resort hotels.', '~$5.99', 5.99, 'BoardWalk Carts', 'food', 'Snack Credit', ARRAY['Plant-based']::text[], null),
  ('s-zebra-domes', 'Zebra Domes', 'AKL', 'snack', 'Chocolate-shell domes filled with Amarula cream liqueur mousse — the Animal Kingdom Lodge''s most famous snack item. Legendary among resort regulars. Available at the Mara quick service even if you''re not staying at the lodge.', '~$5.99', 5.99, null, 'food', 'Snack Credit', null, 's-the-mara'),
  ('s-sanaa-bread-service', 'Sanaa Bread Service', 'AKL', 'snack', 'A selection of artisan breads served with nine accompaniments — tamarind chutney, roasted red pepper hummus, spiced apple butter, and more. Table service item at Sanaa, but so beloved it''s worth a reservation just for this.', '~$18.99', 18.99, null, 'food', 'N/A', null, 'd-sanaa'),
  ('s-banana-bread-with-sea-salt', 'Banana Bread with Sea Salt and Mascarpone', 'RIV', 'snack', 'House-made banana bread topped with sea salt mascarpone — a standout at one of Disney''s best resort quick service locations. A simple, elegant snack that consistently earns rave reviews from food bloggers.', '~$5.99', 5.99, null, 'food', 'Snack Credit', null, 's-primo-piatto'),
  ('s-wilderness-lodge-s-mores', 'Wilderness Lodge S''mores', 'WL', 'snack', 'A tableside s''mores experience at the Territory Lounge bar — graham crackers, chocolate, and marshmallows with a tabletop flame. A cozy, resort-exclusive experience perfect for cooler evenings. Walk-up, no reservation.', '~$10.00', 10.0, null, 'food', 'N/A', null, 'd-territory-lounge'),
  ('s-tie-dye-cheesecake', 'Tie-Dye Cheesecake', 'VALUE', 'snack', 'A psychedelic tie-dye cheesecake on a red velvet cake base — one of the most visually striking desserts at any Disney resort food court. A Pop Century staple that fans travel out of their way to try.', '~$5.49', 5.49, 'Everything POP Dining', 'food', 'Snack Credit', null, null),
  ('s-crab-fries', 'Crab Fries', 'YC', 'snack', 'Loaded fries with crab seasoning, cheese sauce, and Old Bay — available at the pool bar between the Yacht and Beach Clubs at Stormalong Bay. A pool bar standout that gets considerable word-of-mouth.', '~$12.99', 12.99, 'Hurricane Hanna''s Waterside Bar & Grill', 'food', 'QS Credit', null, null),
  ('s-artist-s-palette-roasted', 'Artist''s Palette Roasted Chicken', 'SS', 'snack', 'Roasted half chicken with seasonal vegetables — one of the most-praised items at any Disney resort quick service. Saratoga Springs is often overlooked by non-DVC guests, making this a low-crowd hidden gem.', '~$12.99', 12.99, null, 'food', 'QS Credit', null, 's-the-artist-s-palette')
